INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('interior-design','Interior Design','Full-service design from concept to completion.','We plan your space from the ground up: layout, colour palette, materials, furniture, lighting and décor, then manage the work until it is ready to live in.','https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1600&q=80',0);
INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('interior-decoration','Interior Decoration','Styling, furnishing and finishing touches.','Already happy with the structure? We transform rooms with furniture, curtains, rugs, art, accessories and lighting that reflect your taste.','https://images.unsplash.com/photo-1600210491892-03d54c0aaf87?auto=format&fit=crop&w=1600&q=80',1);
INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('kitchen-design','Kitchen Design & Remodelling','Kitchens that work as good as they look.','Custom kitchen layouts, cabinetry, worktops, islands, storage and lighting, designed around how you cook and entertain.','https://images.unsplash.com/photo-1671197244266-73129c97c096?auto=format&fit=crop&w=1600&q=80',2);
INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('bedroom-styling','Bedroom & Wardrobe Design','Restful bedrooms and smart storage.','Upholstered headboards, built-in wardrobes, bedding and soft furnishings to give you a calm, hotel-like retreat.','https://images.unsplash.com/photo-1616594039964-ae9021a400a0?auto=format&fit=crop&w=1600&q=80',3);
INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('office-commercial','Office & Commercial Fit-out','Workspaces, shops, salons and restaurants.','Commercial interiors that reflect your brand, impress your customers and help your team work better.','https://images.unsplash.com/photo-1604328698692-f76ea9498e76?auto=format&fit=crop&w=1600&q=80',4);
INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('short-let-staging','Short-let & Home Staging','Spaces that rent and sell faster.','We furnish and style short-let apartments and homes for sale so they photograph beautifully and attract more bookings and buyers.','https://images.unsplash.com/photo-1611596188718-840151555242?auto=format&fit=crop&w=1600&q=80',5);
INSERT INTO projects (slug,title,category,location,year,duration,scope,summary,description,cover_image,featured,sort_order) VALUES ('warm-contemporary-living-room','Warm Contemporary Living Room','Residential','Abuja','2026','6 weeks','Living room redesign, custom sofa, lighting, art curation','A bright family living room reworked around soft neutrals, natural wood and layered lighting.','The brief was a living room that feels calm in the day and cosy at night. We opened up the layout, introduced a custom low-profile sofa, warm oak accents and a layered lighting plan with dimmable pendants and wall washers. Curtains, rugs and art were sourced to pull the palette together, leaving a space that works for everyday family life and for hosting guests.','https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1600&q=80',1,0);
